#!/usr/bin/env bash
# RunX Player 1.0.1+89 — remove the VPN feature, bring Cloud Storage back,
# and sync the privacy policy + user manual.
#
# WHY: Play rejected the release with "Some types of apps can only be
# distributed by organizations". Apps using android.permission.BIND_VPN_SERVICE
# must be published from an Organization account; this is a personal account,
# so the VPN cannot ship - and that also removes the 8.7 MB OpenVPN/OpenSSL
# native payload, the VpnService declaration and the AD_ID/Data-safety churn.
#
# WHAT CHANGES (30 paths)
#   Android
#     * AndroidManifest.xml: VpnService <service> (BIND_VPN_SERVICE) removed
#     * build.gradle.kts: com.wireguard.android:tunnel dependency removed
#     * proguard-rules.pro: VPN keep rules removed
#     * MaxVpnManager.java, VpnSecretStore.java deleted; the "maxplayer/vpn"
#       MethodChannel and its onActivityResult hook removed from MainActivity.kt
#   Dart
#     * lib/features/vpn/** deleted (screen, controller, bridge, disclosure)
#     * quick tile "vpn" -> "cloudStorage" (Cloud Storage is back on page 2)
#     * analytics feature key "vpn" -> "cloud"; notification destination "vpn"
#       removed (the "cloud" destination already existed)
#   Docs
#     * privacy policy: the "Optional VPN" section is replaced by
#       "Cloud Storage and network locations" in all three copies (in-app text,
#       PRIVACY_POLICY.md, privacy/index.html) - the public copies are
#       regenerated from the in-app constant so they cannot drift again
#     * USER_MANUAL.md + the in-app manual: VPN section replaced by Cloud
#       Storage, Discover Back / tablet notes added
#     * third_party/vpn (GPL notice for the removed engine) deleted
#   Version
#     * pubspec 1.0.1+88 -> 1.0.1+89, kAppVersionTag +88 -> +89
#   Tests
#     * vpn_ui81_test.dart, vpn_disclosure_tablet88_test.dart deleted
#     * the VPN case in vpn_gestures86_test.dart removed
#     * quick_tiles_test / feature_crash_test / ui_theme82_test / widget_test
#       updated for Cloud Storage and the +89 tag
#
# Usage — run from your existing repository root (this repo is already +88):
#   bash update_android_vpn_removal_v89.sh --check     # dry run
#   bash update_android_vpn_removal_v89.sh             # apply
#   bash update_android_vpn_removal_v89.sh --verify    # re-check later
#
# Then:
#   flutter pub get && flutter analyze --no-fatal-infos && flutter test
#   git add -A && git commit -m "1.0.1+89: remove VPN (org-account policy), restore Cloud Storage"
#   git push origin main
#
# In Play Console after the build:
#   * App content -> VPN service: "My app does not use VpnService" is now true.
#   * Advertising ID: "No" (nothing in the app brings AD_ID back).
#   * Data safety: remove nothing else - Cloud Storage credentials stay on-device.
set -euo pipefail
command -v python3 >/dev/null || { echo 'Python 3 is required'; exit 1; }
python3 - "$@" <<'ANDVPN89_PY'
