N30GAA=="""


def fail(message):
    print('STOP: ' + message, file=sys.stderr)
    sys.exit(1)


def digest(data):
    return hashlib.sha256(data).hexdigest()


args = sys.argv[1:]
if not args:
    args = ['--apply']
if len(args) != 1 or args[0] not in ['--check', '--apply', '--verify']:
    fail('Use no argument (apply), --check, --apply or --verify from the repository root.')
mode = args[0]

blob = ''.join(PAYLOAD.split())
if hashlib.sha256(blob.encode()).hexdigest() != PAYLOAD_HASH:
    fail('Payload is corrupted (checksum mismatch). Re-download the script.')
entries = json.loads(gzip.decompress(base64.b64decode(blob)))

try:
    root = pathlib.Path(subprocess.check_output(
        ['git', 'rev-parse', '--show-toplevel'], stderr=subprocess.DEVNULL
    ).decode().strip()).resolve()
except Exception:
    fail('Not inside a Git repository.')
if pathlib.Path.cwd().resolve() != root:
    fail('Run from your existing repository root; no files changed.')

pubspec = root / 'pubspec.yaml'
if not pubspec.is_file() or 'name: maxplayer' not in pubspec.read_text(encoding='utf-8'):
    fail('pubspec.yaml for maxplayer not found in this repository.')

if mode == '--verify':
    bad = []
    for e in entries:
        p = root / e['path']
        actual = digest(p.read_bytes()) if p.exists() else None
        if actual != e['after']:
            bad.append('  ' + e['path'])
    if bad:
        fail('Not in the +89 state:\n' + '\n'.join(bad))
    print('VERIFIED: all %d payload hashes match.' % len(entries))
    sys.exit(0)

if mode == '--apply' and 'version: 1.0.1+88' not in pubspec.read_text(encoding='utf-8'):
    fail('Expected "version: 1.0.1+88" in pubspec.yaml. This payload is built for the '
         '+88 tree (after the play/store and privacy scripts). Do not force it.')

todo, problems = [], []
for e in entries:
    p = root / e['path']
    actual = digest(p.read_bytes()) if p.exists() else None
    if e['before'] is None:
        if actual is not None:
            problems.append('  %s already exists' % e['path'])
            continue
    elif actual != e['before']:
        if actual == e['after']:
            continue  # already patched
        problems.append('  %s does not match the expected +88 contents' % e['path'])
        continue
    todo.append(e)

if problems:
    fail('These paths are unexpected:\n' + '\n'.join(problems))

print('VPN removal payload: %d paths; %d need changes.' % (len(entries), len(todo)))
if mode == '--check':
    for e in todo:
        print(('  delete  ' if e['data'] is None else '  write   ') + e['path'])
    print('CHECK PASSED. No files written.')
    print('Next: apply, then flutter pub get / analyze / test, then commit and build.')
    sys.exit(0)

for e in todo:
    p = root / e['path']
    if e['data'] is None:
        if p.exists():
            p.unlink()
        continue
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(e['data']))

# drop directories left empty by the deletions
for rel in ['lib/features/vpn', 'third_party/vpn', 'third_party']:
    d = root / rel
    if d.is_dir() and not any(d.iterdir()):
        d.rmdir()

print('Applied %d change(s):' % len(todo))
print('')
print('Next:')
print('  flutter pub get && flutter analyze --no-fatal-infos && flutter test')
print('  git add -A && git commit -m "1.0.1+89: remove VPN (org-account policy), restore Cloud Storage"')
print('  git push origin main')
print('Then in Play Console: VPN service declaration -> does not use VpnService,')
print('Advertising ID -> No, Data safety unchanged for Cloud Storage.')
